function shoeProfileRecord(family,version,opts={}){
 const base={brand:'ASICS',family,version,neutral:true,surfaces:['road'],roles:['daily','easy'],cushioning:3,responsiveness:3,stability:3,protection:3,grip:3,efficiency:3,durability:3,comfort:3,weightClass:'medium',plated:false,plateType:null,preferredDistanceMinKm:3,preferredDistanceMaxKm:35,typicalReplacementLowKm:600,typicalReplacementHighKm:850,manufacturerPositioning:'Neutral road-running shoe.',evidenceSource:'Official ASICS product positioning/specifications; practical suitability scores are app-derived.',profileConfidence:'medium'};
 const x={...base,...opts};
 x.workoutSuitability={};SHOE_WORKOUT_KEYS.forEach(k=>x.workoutSuitability[k]=shoeProfileWorkoutSuitability(x,k));return x;
}
function shoeProfileWorkoutSuitability(p,type){
 const roles=new Set(p.roles||[]),t=String(type||'');let s=55;
 if(/Recovery|Shakeout/.test(t))s+=(roles.has('recovery')||roles.has('easy'))?20:0;
 if(/Easy|Steady/.test(t))s+=(roles.has('daily')||roles.has('easy')||roles.has('steady'))?18:0;
 if(/Medium-long|Long run/.test(t))s+=(roles.has('long')||roles.has('daily'))?20:0;
 if(/Progression/.test(t))s+=(roles.has('progression')||roles.has('tempo')||roles.has('long'))?20:0;
 if(/Threshold|Fartlek/.test(t))s+=(roles.has('tempo')||roles.has('threshold')||roles.has('intervals'))?22:0;
 if(/VO₂|max|Fitness assessment/.test(t))s+=(roles.has('intervals')||roles.has('race'))?25:0;
 if(/Race-pace|Specific|Race rehearsal|Marathon-specific|Half-marathon-specific/.test(t))s+=(roles.has('race')||roles.has('tempo')||roles.has('long'))?22:0;
 if(/Race$|Race Day/.test(t))s+=roles.has('race')?35:-25;
 if(/Hills/.test(t))s+=Number(p.grip)>=4?15:0;
 return clamp(Math.round(s),0,100);
}
const ASICS_SHOE_PROFILES=[];
